// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address addr1, address addr2) public {
        // Ensure addresses are distinct for allowance call
        vm.assume(addr1 != addr2);

        // Get the initial owner
        address initialOwner = c.owner();

        // Make some state-changing calls (allowance is a view function but we need to trigger any potential changes)
        // Use prank to simulate different callers
        vm.prank(addr1);
        c.allowance(addr1, addr2);

        // Get the owner again after some operations
        address finalOwner = c.owner();

        // The general rule: owner() should return the same address regardless of state changes
        assertTrue(initialOwner == finalOwner, "Owner address changed between calls");
    }
}

