        vm.assume(newOwner != address(0) && newOwner != address(this));

        // Get the current owner from the contract
        address currentOwner = c.owner();

        // Try to set a new caller via setCaller (onlyOwner) - should succeed if owner() returns the real owner
        vm.prank(currentOwner);
        try c.setCaller(newOwner) {
            // If setCaller succeeded, check that the new owner can now call setCaller
            vm.prank(newOwner);
            try c.setCaller(address(0x1234)) {
                assertTrue(true);
            } catch {
                assertTrue(false);
            }
        } catch {
            assertTrue(false);
        }
    }
}

