pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address spender, uint256 amount) public {
        // Assume spender is not zero address to avoid approve revert
        vm.assume(spender != address(0));

        // Initial state: owner approves some amount
        c.approve(spender, amount);
        uint256 prevAllowance = c.allowance(address(this), spender);

        // Transfer ownership to zero address (may revert in buggy version)
        // Use try/catch to handle potential revert in buggy contract
        try c.transferOwnership(address(0)) {
            // If successful, check that allowance remains unchanged
            uint256 newAllowance = c.allowance(address(this), spender);
            assertTrue(newAllowance == prevAllowance, "Allowance changed after ownership transfer");
        } catch {
            // If revert, the buggy version made it impossible, so we assert false directly
            assertTrue(false, "Ownership transfer to zero address reverted unexpectedly");
        }
    }
}

