pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        // bound amounts to avoid overflow
        amount1 = bound(amount1, 0, 1e30);
        amount2 = bound(amount2, 0, 1e30);
        // ensure addresses are not zero and different from each other
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        // mint tokens to addr1 and addr2
        vm.prank(c.owner());
        c.transfer(addr1, amount1);
        vm.prank(c.owner());
        c.transfer(addr2, amount2);
        // compute sum of balances
        uint256 sumBalances;
        unchecked {
            sumBalances = c.balanceOf(addr1) + c.balanceOf(addr2) + c.balanceOf(address(this)) + c.balanceOf(address(c)) + c.balanceOf(c.owner()) + c.balanceOf(c.pairAddress());
        }
        // the rule: totalSupply equals sum of all balances
        assertTrue(c.totalSupply() == sumBalances);
    }
}

