pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address a1, address a2, uint256 amount1, uint256 amount2) public {
        // Restrict amounts to avoid overflow and ensure they are within total supply
        vm.assume(amount1 <= 1e30 && amount2 <= 1e30);

        // Perform some transfers to create balances
        vm.assume(a1 != address(0) && a2 != address(0));
        vm.assume(a1 != a2);

        // Transfer tokens to a1 and a2 (simplified: we can use the contract's owner balance)
        // Since the owner has initial supply, we can transfer from owner to a1 and a2
        vm.prank(address(this)); // The owner is address(this) in setUp
        c.transfer(a1, amount1);
        vm.prank(address(this));
        c.transfer(a2, amount2);

        // Now compute sum of balances for a set of addresses (including pair, helper, owner)
        uint256 sumBalances = c.balanceOf(a1) + c.balanceOf(a2) + c.balanceOf(address(this)) + c.balanceOf(c.pairAddress()) + c.balanceOf(c.helperAddress());
        uint256 totalSupply = c.totalSupply();

        // The sum of balances of all addresses that may hold tokens should equal totalSupply
        // Note: We cannot enumerate all addresses, but we can check that totalSupply is at least the sum of a known set
        assertTrue(totalSupply >= sumBalances);
    }
}

