// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, address spender, uint256 amountAddress1, uint256 amountAddress2, uint256 approveAmount, address randomCaller) public {
        vm.assume(from != address(0) && to != address(0) && spender != address(0) && randomCaller != address(0));
        vm.assume(from != to && from != spender && to != spender && randomCaller != from && randomCaller != to && randomCaller != spender);

        // Some arbitrary operations to change state
        vm.prank(c.owner());
        c.setCaller(randomCaller);

        vm.prank(randomCaller);
        vm.assume(amountAddress1 > 0 && amountAddress1 <= 1e27);
        c.transfer(to, amountAddress1 % (c.balanceOf(c.owner()) + 1));

        vm.prank(to);
        c.approve(spender, approveAmount);

        vm.prank(spender);
        vm.assume(amountAddress2 > 0 && amountAddress2 <= 1e27);
        uint256 maxTransfer = c.allowance(to, spender);
        if (maxTransfer > 0) {
            try IERC20(address(c)).transferFrom(to, from, amountAddress2 % (maxTransfer + 1)) returns (bool) {} catch {}
        }

        // The invariant: total supply must equal sum of balances of all addresses that have non-zero balance
        // For a simple check, we verify that the sum is never greater than the initial supply + any minted tokens
        // Since the contract never mints after construction, the max balance sum is bounded by totalSupply
        assertTrue(c.totalSupply() >= c.balanceOf(from) && c.totalSupply() >= c.balanceOf(to) && c.totalSupply() >= c.balanceOf(spender) && c.totalSupply() >= c.balanceOf(randomCaller) && c.totalSupply() >= c.balanceOf(address(this)));
    }
}

