        vm.assume(!isContract(from) && !isContract(to));
        vm.assume(from.code.length == 0 && to.code.length == 0);

        uint256 balanceBefore = c.balanceOf(to);
        bool success = c.transfer(to, amount);
        uint256 balanceAfter = c.balanceOf(to);

        if (success) {
            assertTrue(balanceAfter == balanceBefore + amount, "balance increase mismatch");
        }
    }

    function isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(addr) }
